// generated by chatgpt: Saves the previous position, moves the bullet by its heading, rebuilds its movement bounds, and kills it when it leaves the window; the updated state is used by rendering, collision detection, and object cleanup.
void Bullet::Update(CMPUT350::GameContext* context)
{
    mPreviousLocation = mLocation;
    mLocation += mHeading;
    mBounds = CMPUT350::Rect(mPreviousLocation, mLocation);
    //if bullet is out of screen, kill it
    if (mLocation.x < 0 ||
        mLocation.x > context->ScreenContext->GetWindowWidth() ||
        mLocation.y < 0 ||
        mLocation.y > context->ScreenContext->GetWindowHeight())
    {
        Kill();
    }
}

