const std::vector<CMPUT350::Shape> &Bullet::GetShapes()
{
    mShapes.clear();
    CMPUT350::Point2D start = mPreviousLocation- mLocation;
    CMPUT350::Point2D end(0, 0);
    mShapes.emplace_back(CMPUT350::Line(start, end));
    return mShapes;
}

